<?php
$this->layout('layouts/studio');
$first = strtotime($month . '-01');
$start = (int)date('N', $first);
$days = (int)date('t', $first);
$byDay = [];
foreach ($events as $event) $byDay[(int)date('j', strtotime($event->starts_at))][] = $event;
$monthLabel = class_exists(\IntlDateFormatter::class)
    ? (new \IntlDateFormatter('pt_BR', \IntlDateFormatter::NONE, \IntlDateFormatter::NONE, date_default_timezone_get(), null, "MMMM 'de' yyyy"))->format($first)
    : date('m/Y', $first);
?>
<section class="studio-page-head organic-page-header"><div><p class="organic-eyebrow">Atendimento</p><h1 class="organic-page-title">Agenda</h1><p class="organic-page-description">Organize atendimentos, tarefas e compromissos do time em uma visão mensal.</p></div><button class="organic-btn organic-btn-primary" type="button" data-agenda-new><ion-icon name="add-outline"></ion-icon>Novo evento</button></section>
