    <label>Status<select class="organic-select" name="status"><option value="">Todos</option><?php foreach(['scheduled'=>'Agendado','completed'=>'Concluído','cancelled'=>'Cancelado'] as $value=>$label):?><option value="<?= $value ?>" <?= $statusFilter===$value?'selected':'' ?>><?= $label ?></option><?php endforeach;?></select></label>
    <label>Responsável<select class="organic-select" name="assigned_to"><option value="">Todos</option><?php foreach($users as $item):?><option value="<?= $item->id ?>" <?= $assignedFilter==$item->id?'selected':'' ?>><?= htmlspecialchars($item->fullName()) ?></option><?php endforeach;?></select></label>
    <button class="organic-btn" type="submit"><ion-icon name="filter-outline"></ion-icon>Aplicar</button>
